'use strict';

/*
 * Tests for scripts/browser-tests.js, the runner behind the `browser` CI job (ADR 0069).
 *   (a) the frozen file list equals the set of test files that read the Playwright env var
 *   (b) the TAP summary parser, the failed-test lister, the child-outcome mapper and the verdict
 *   (c) the package specs are exact versions
 *   (d) the versions live in one place: no other tracked text carries a version token
 * The TAP fixtures below are hand-written to the shape Node 22 prints with --test-reporter=tap
 * (observed on Node v22.22.3). They are never generated by the parser under test.
 * Version tokens in this file are built from pieces so the file carries no literal.
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');

const runner = require('../scripts/browser-tests.js');

const ROOT = path.join(__dirname, '..');
const SELF = path.join('test', 'browser-tests.test.js');

// Built from pieces so this file does not match itself.
const ENV_TOKEN = ['process', 'env', 'PLAYWRIGHT_MODULE'].join('.');

function walk(dir, keep, skipDir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!skipDir(full, entry.name)) out.push(...walk(full, keep, skipDir));
    } else if (keep(entry.name)) out.push(full);
  }
  return out.sort();
}

/** Repo-relative POSIX paths of every test/**\/*.test.js whose source holds the env token. */
function scanBrowserFiles(root) {
  const files = walk(
    path.join(root, 'test'),
    (n) => n.endsWith('.test.js'),
    (_f, n) => n === 'node_modules',
  );
  return files
    .filter((f) => fs.readFileSync(f, 'utf8').includes(ENV_TOKEN))
    .map((f) => path.relative(root, f).split(path.sep).join('/'));
}

/** Compare a list against what a tree actually holds: { unlisted, stale }. */
function compareList(root, list) {
  const found = scanBrowserFiles(root);
  return {
    unlisted: found.filter((f) => !list.includes(f)),
    stale: list.filter((f) => !found.includes(f)),
  };
}

// ---------------------------------------------------------------- (a) completeness

test('(a) BROWSER_TEST_FILES equals the set of test files that read the Playwright env var', () => {
  assert.deepEqual(compareList(ROOT, runner.BROWSER_TEST_FILES), { unlisted: [], stale: [] });
});

test('(a) the list is frozen, sorted and exists on disk', () => {
  const list = runner.BROWSER_TEST_FILES;
  assert.ok(Object.isFrozen(list));
  assert.deepEqual([...list], [...list].sort());
  for (const f of list) assert.ok(fs.existsSync(path.join(ROOT, f)), f);
});

test('(a) every *.dom.test.js is listed, and so is story-nav-pin.test.js', () => {
  const dom = walk(
    path.join(ROOT, 'test'),
    (n) => n.endsWith('.dom.test.js'),
    (_f, n) => n === 'node_modules',
  ).map((f) => path.relative(ROOT, f).split(path.sep).join('/'));
  assert.ok(dom.length > 0);
  for (const f of dom) assert.ok(runner.BROWSER_TEST_FILES.includes(f), f);
  assert.ok(runner.BROWSER_TEST_FILES.includes('test/story-nav-pin.test.js'));
});

test('(a) controls: a planted unlisted file and a stale listed file are both reported', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'browser-list-'));
  try {
    fs.mkdirSync(path.join(dir, 'test', 'sub'), { recursive: true });
    fs.writeFileSync(path.join(dir, 'test', 'a.dom.test.js'), `const m = ${ENV_TOKEN};\n`);
    fs.writeFileSync(path.join(dir, 'test', 'sub', 'planted.test.js'), `x(${ENV_TOKEN});\n`);
    fs.writeFileSync(path.join(dir, 'test', 'plain.test.js'), 'const x = 1;\n');
    // a clean list passes
    assert.deepEqual(compareList(dir, ['test/a.dom.test.js', 'test/sub/planted.test.js']), { unlisted: [], stale: [] });
    // the planted file is not listed
    assert.deepEqual(compareList(dir, ['test/a.dom.test.js']).unlisted, ['test/sub/planted.test.js']);
    // a listed file without the token is stale
    assert.deepEqual(compareList(dir, ['test/a.dom.test.js', 'test/sub/planted.test.js', 'test/plain.test.js']).stale, [
      'test/plain.test.js',
    ]);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------- (b) TAP parsing and verdict

const CLEAN = [
  'TAP version 13',
  '# Subtest: a thing',
  'ok 1 - a thing',
  '  ---',
  '  duration_ms: 0.079698',
  "  type: 'test'",
  '  ...',
  '1..1',
  '# tests 12',
  '# suites 3',
  '# pass 12',
  '# fail 0',
  '# cancelled 0',
  '# skipped 0',
  '# todo 0',
  '# duration_ms 314994.69',
  '',
].join('\n');

const withLine = (text, from, to) => {
  const out = text.replace(from, to);
  assert.notEqual(out, text, `fixture change did nothing: ${from}`);
  return out;
};

test('(b) parseSummary reads every key, including a fractional duration and the suites and todo lines', () => {
  assert.deepEqual(runner.parseSummary(CLEAN), {
    tests: 12,
    pass: 12,
    fail: 0,
    cancelled: 0,
    skipped: 0,
    todo: 0,
    durationMs: 314994.69,
  });
});

test('(b) parseSummary gives null for absent keys and for no summary at all', () => {
  const s = runner.parseSummary('TAP version 13\nok 1 - x\n');
  assert.deepEqual(s, { tests: null, pass: null, fail: null, cancelled: null, skipped: null, todo: null, durationMs: null });
});

test('(b) parseSummary: the last occurrence wins, indented lines are ignored', () => {
  const noisy = `# tests 99\n# fail 7\n  # tests 55\n${CLEAN}`;
  const s = runner.parseSummary(noisy);
  assert.equal(s.tests, 12);
  assert.equal(s.fail, 0);
  // an unindented diagnostic AFTER the real summary would win: documents the rule
  assert.equal(runner.parseSummary(`${CLEAN}# tests 3\n`).tests, 3);
  // only the indented copy: not read
  assert.equal(runner.parseSummary('  # tests 55\n').tests, null);
});

test('(b) a clean summary and a clean exit give no reasons', () => {
  assert.deepEqual(runner.verdict(runner.parseSummary(CLEAN), runner.childOutcome({ status: 0, signal: null })), []);
});

test('(b) each failure reason shows up', () => {
  const ok = runner.childOutcome({ status: 0, signal: null });
  const v = (text, outcome = ok) => runner.verdict(runner.parseSummary(text), outcome);
  assert.deepEqual(v(withLine(CLEAN, '# fail 0', '# fail 1')), ['fail=1']);
  assert.deepEqual(v(withLine(CLEAN, '# skipped 0', '# skipped 2')), ['skipped=2']);
  assert.deepEqual(v(withLine(CLEAN, '# cancelled 0', '# cancelled 3')), ['cancelled=3']);
  assert.deepEqual(v(withLine(CLEAN, '# todo 0', '# todo 1')), ['todo=1']);
  assert.deepEqual(v(withLine(CLEAN, '# tests 12', '# tests 0')), ['zero-tests']);
  assert.deepEqual(v('TAP version 13\nok 1 - x\n'), ['no-summary']);
  assert.deepEqual(v(CLEAN, runner.childOutcome({ status: 1, signal: null })), ['exit=1']);
});

test('(b) several reasons are all reported', () => {
  const text = withLine(withLine(CLEAN, '# fail 0', '# fail 2'), '# skipped 0', '# skipped 1');
  assert.deepEqual(runner.verdict(runner.parseSummary(text), runner.childOutcome({ status: 1, signal: null })), [
    'fail=2',
    'skipped=1',
    'exit=1',
  ]);
});

test('(b) an earlier tests 99 diagnostic does not hide a final zero-test summary', () => {
  const text = withLine(CLEAN, '# tests 12', '# tests 0');
  assert.deepEqual(runner.verdict(runner.parseSummary(`# tests 99\n${text}`), []), ['zero-tests']);
});

test('(b) childOutcome: clean, exit codes, signal, null status, spawn error', () => {
  assert.deepEqual(runner.childOutcome({ status: 0, signal: null, error: undefined }), []);
  assert.deepEqual(runner.childOutcome({ status: 2, signal: null }), ['exit=2']);
  assert.deepEqual(runner.childOutcome({ status: null, signal: 'SIGKILL' }), ['signal=SIGKILL', 'exit=null']);
  assert.deepEqual(runner.childOutcome({ status: null, signal: null }), ['exit=null']);
  const timeout = Object.assign(new Error('spawnSync node ETIMEDOUT'), { code: 'ETIMEDOUT' });
  assert.deepEqual(runner.childOutcome({ status: null, signal: 'SIGKILL', error: timeout }), [
    'spawn-error=ETIMEDOUT',
    'signal=SIGKILL',
    'exit=null',
  ]);
  const nobuf = Object.assign(new Error('x'), { code: 'ENOBUFS' });
  assert.ok(runner.childOutcome({ status: 0, signal: null, error: nobuf }).includes('spawn-error=ENOBUFS'));
  // an error with no code still gives a reason
  assert.equal(runner.childOutcome({ status: 0, signal: null, error: new Error('x') }).length, 1);
  // no result object at all is a failure, never a pass
  assert.ok(runner.childOutcome(undefined).length > 0);
});

test('(b) a clean summary from a killed child still fails', () => {
  const summary = runner.parseSummary(CLEAN);
  const killed = runner.verdict(summary, runner.childOutcome({ status: null, signal: 'SIGKILL' }));
  assert.ok(killed.length > 0);
  assert.ok(killed.includes('signal=SIGKILL'));
  const enobufs = Object.assign(new Error('x'), { code: 'ENOBUFS' });
  assert.ok(runner.verdict(summary, runner.childOutcome({ status: null, signal: null, error: enobufs })).length > 0);
});

test('(b) failedTests lists names at any indent, including the #137 shape of subtest plus parent', () => {
  const tap = [
    'TAP version 13',
    '# Subtest: start a new campaign, browsing in chromium',
    '    # Subtest: the output question: an unchanged answer is not ticked',
    '    not ok 1 - the output question: an unchanged answer is not ticked',
    '      ---',
    "      type: 'test'",
    '      ...',
    'not ok 1 - start a new campaign, browsing in chromium',
    '  ---',
    "  type: 'test'",
    '  ...',
    'ok 2 - something else',
    '',
  ].join('\n');
  assert.deepEqual(runner.failedTests(tap), [
    'the output question: an unchanged answer is not ticked',
    'start a new campaign, browsing in chromium',
  ]);
  assert.deepEqual(runner.failedTests(CLEAN), []);
});

test('(b) failedTests ignores todo and skip directive lines', () => {
  const tap = [
    'not ok 2 - todo fail # TODO',
    'ok 3 - skipped # SKIP',
    'not ok 4 - todo with reason # TODO later',
    'not ok 5 - skipped not ok # SKIP because',
    'not ok 6 - bad',
    'not ok 7 - has a # hash in the name',
    '',
  ].join('\n');
  assert.deepEqual(runner.failedTests(tap), ['bad', 'has a # hash in the name']);
});

// ---------------------------------------------------------------- (c) package specs

test('(c) packageSpecs are exact pins with no range characters', () => {
  const specs = runner.packageSpecs();
  assert.equal(specs.length, 2);
  assert.match(specs[0], /^playwright@\d+\.\d+\.\d+$/);
  assert.match(specs[1], /^axe-core@\d+\.\d+\.\d+$/);
  assert.equal(specs[0], 'playwright@' + runner.PLAYWRIGHT_VERSION);
  assert.equal(specs[1], 'axe-core@' + runner.AXE_CORE_VERSION);
  for (const s of specs) assert.doesNotMatch(s, /[\^~*><=\s]/);
});

test('(c) main packages prints the specs on one line and returns 0; usage errors return 1', () => {
  const lines = [];
  const orig = console.log;
  console.log = (l) => lines.push(l);
  try {
    assert.equal(runner.main(['packages']), 0);
    assert.equal(runner.main([]), 1);
    assert.equal(runner.main(['bogus']), 1);
    assert.equal(runner.main(['packages', 'extra']), 1);
  } finally {
    console.log = orig;
  }
  assert.equal(lines[0], runner.packageSpecs().join(' '));
  assert.match(lines[1], /^BROWSER-TESTS FAIL usage: /);
  assert.equal(lines.length, 4);
});

// ---------------------------------------------------------------- (d) one place for the versions

const TOKEN_RE = /\b(playwright|axe-core)@(\d[^\s`'")\]]*)/g;
const TEXT_EXT = new Set(['.md', '.js', '.mjs', '.cjs', '.json', '.yml', '.yaml', '.html', '.css', '.txt']);
const DOCS_HOME = 'docs/DEVELOPING.md';

/** Every version token in the tracked text of a tree: [{ file, name, version }]. */
function findTokens(root) {
  const skip = (full, name) => {
    const rel = path.relative(root, full).split(path.sep).join('/');
    return name === 'node_modules' || name === 'vendor' || rel === 'test/fixtures' || rel === 'docs/agent-runs';
  };
  const files = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isFile() && entry.name.endsWith('.md')) files.push(path.join(root, entry.name));
  }
  for (const dir of ['docs', '.agents', '.github', 'scripts', 'src', 'test']) {
    files.push(...walk(path.join(root, dir), (n) => TEXT_EXT.has(path.extname(n)), skip));
  }
  const hits = [];
  for (const f of files) {
    const rel = path.relative(root, f).split(path.sep).join('/');
    if (rel === SELF.split(path.sep).join('/')) continue;
    const text = fs.readFileSync(f, 'utf8');
    for (const m of text.matchAll(TOKEN_RE)) hits.push({ file: rel, name: m[1], version: m[2].replace(/[.,;:]+$/, '') });
  }
  return hits;
}

/** What is wrong with a hit list: a hit outside the docs home, or a version that differs. */
function tokenProblems(hits, expected) {
  const problems = [];
  for (const h of hits) {
    if (h.file !== DOCS_HOME) problems.push(`${h.file}: ${h.name} token outside ${DOCS_HOME}`);
    else if (h.version !== expected[h.name]) problems.push(`${h.file}: ${h.name} version ${h.version} differs`);
  }
  return problems;
}

const EXPECTED = { playwright: runner.PLAYWRIGHT_VERSION, 'axe-core': runner.AXE_CORE_VERSION };

test('(d) the versions appear only in scripts/browser-tests.js and, equal to it, in docs/DEVELOPING.md', () => {
  assert.deepEqual(tokenProblems(findTokens(ROOT), EXPECTED), []);
});

/** How many hits name `name` in the docs home. */
const countIn = (hits, name) => hits.filter((h) => h.file === DOCS_HOME && h.name === name).length;

test('(d) docs/DEVELOPING.md carries at least one token of each tool', () => {
  const hits = findTokens(ROOT);
  assert.ok(countIn(hits, 'playwright') >= 1, 'no playwright token in DEVELOPING');
  assert.ok(countIn(hits, 'axe-core') >= 1, 'no axe-core token in DEVELOPING');
  // control: the counter sees a present token and an absent one
  const sample = [{ file: DOCS_HOME, name: 'playwright', version: '0' }];
  assert.equal(countIn(sample, 'playwright'), 1);
  assert.equal(countIn(sample, 'axe-core'), 0);
  assert.equal(countIn([{ file: 'README.md', name: 'axe-core', version: '0' }], 'axe-core'), 0);
});

test('(d) controls: a wrong version, a stray token and a matching token', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'browser-tokens-'));
  try {
    fs.mkdirSync(path.join(dir, 'docs', 'decisions'), { recursive: true });
    fs.mkdirSync(path.join(dir, 'docs', 'agent-runs'), { recursive: true });
    fs.mkdirSync(path.join(dir, 'test', 'fixtures'), { recursive: true });
    fs.mkdirSync(path.join(dir, 'node_modules', 'x'), { recursive: true });
    const good = `npm install playwright@${EXPECTED.playwright} axe-core@${EXPECTED['axe-core']}\n`;
    const wrongPw = 'playwright@' + ['9', '9', '9'].join('.');
    const wrongAxe = 'axe-core@' + ['0', '0', '1'].join('.');
    // matching tokens in the docs home pass
    fs.writeFileSync(path.join(dir, 'docs', 'DEVELOPING.md'), good);
    assert.deepEqual(tokenProblems(findTokens(dir), EXPECTED), []);
    assert.equal(findTokens(dir).length, 2);
    // a wrong version in the docs home is caught
    fs.writeFileSync(path.join(dir, 'docs', 'DEVELOPING.md'), `${wrongPw} and ${wrongAxe}.\n`);
    assert.equal(tokenProblems(findTokens(dir), EXPECTED).length, 2);
    fs.writeFileSync(path.join(dir, 'docs', 'DEVELOPING.md'), good);
    // a token anywhere else is caught: the ADR, a root doc, a workflow
    fs.writeFileSync(path.join(dir, 'docs', 'decisions', '0001-x.md'), good);
    fs.writeFileSync(path.join(dir, 'README.md'), good);
    fs.mkdirSync(path.join(dir, '.github', 'workflows'), { recursive: true });
    fs.writeFileSync(path.join(dir, '.github', 'workflows', 'ci.yml'), `- run: npm i ${good}`);
    const files = tokenProblems(findTokens(dir), EXPECTED).map((p) => p.split(':')[0]);
    assert.deepEqual(files.sort(), ['.github/workflows/ci.yml', '.github/workflows/ci.yml', 'README.md', 'README.md', 'docs/decisions/0001-x.md', 'docs/decisions/0001-x.md']);
    // excluded places are not scanned
    fs.rmSync(path.join(dir, 'docs', 'decisions'), { recursive: true, force: true });
    fs.rmSync(path.join(dir, 'README.md'));
    fs.rmSync(path.join(dir, '.github'), { recursive: true, force: true });
    fs.writeFileSync(path.join(dir, 'docs', 'agent-runs', 'a.md'), good);
    fs.writeFileSync(path.join(dir, 'test', 'fixtures', 'a.md'), good);
    fs.writeFileSync(path.join(dir, 'node_modules', 'x', 'a.md'), good);
    assert.equal(findTokens(dir).length, 2);
    // a token with no digit after the at sign is not a version token
    fs.writeFileSync(path.join(dir, 'docs', 'DEVELOPING.md'), 'the playwright@ and axe-core@ names\n');
    assert.deepEqual(findTokens(dir), []);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
